dition:9789021417363","work_id":2182,"bound_author_id":7,"bound_title":"Duin Kapittel","bound_language":"nld","bound_isbn13":"9789021417363","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000525827_Duin_Kapittel_0_0.jpg","card_cover_url":"https://metadata.isbn.nl/ie_fcache/0000525827_Duin_Kapittel_2_710_130_0_0.jpg","evidence_url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","evidence":[{"url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","isbn":"9789021417363","checkedAt":"2026-10-31","facts":"Frank Herbert; Bene Gesserit/Matres; explicitly Duin #6. Library identifies original Chapterhouse: Dune (1985).","format":"hardcover","language":"nld"},{"url":"https://rozet.nl/catalogus/1953590/","role":"Independent exact-edition identity/language corroboration","checkedAt":"2026-10-31"},{"url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","role":"Same edition thumbnail actually embedded by registry","coverUrl":"https://metadata.isbn.nl/ie_fcache/0000525827_Duin_Kapittel_2_710_130_0_0.jpg","sha256":"49692de774cde00157886a07f294916966320b058f3f3ecbf63526cd7fcfb4b1","checkedAt":"2026-10-31T15:09:03.532Z"}],"review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"reviewed-cover:9789021417363"},{"relation":"editions","ref":"edition:9780593201763","key":{"isbn_13":"9780593201763"},"before":null,"after":{"work_id":311,"title":"Heretics of Dune","isbn_13":"9780593201763","isbn_10":null,"language":"eng","publisher":"Ace","open_library_edition_id":"OL29887746M"},"origin":"reviewed:9780593201763"},{"relation":"catalog_edition_metadata","key":{"edition_id":"@edition:9780593201763"},"before":null,"after":{"edition_id":"@edition:9780593201763","work_id":311,"bound_author_id":7,"bound_title":"Heretics of Dune","bound_language":"eng","bound_isbn13":"9780593201763","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/14630302-L.jpg?default=false","card_cover_url":null,"evidence_url":"https://www.penguinrandomhouse.com/books/303821/heretics-of-dune-by-frank-herbert/paperback/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/303821/heretics-of-dune-by-frank-herbert/paperback/","isbn":"9780593201763","checkedAt":"2026-10-31","facts":"Reuses previously approved test edition91021201; exact ISBN/English OL language/parent OL893502W and publisher fifth-volume paperback checked anew. Existing unknown-language audio ISBN9780694510221 remains unchanged.","format":"paperback","language":"eng"}],"review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"reviewed-cover:9780593201763"},{"relation":"catalog_edition_metadata","key":{"edition_id":2376},"before":null,"after":{"edition_id":2376,"work_id":311,"bound_author_id":7,"bound_title":"Ketters van Duin","bound_language":"dut","bound_isbn13":"9789029043151","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/12714357-L.jpg?default=false","card_cover_url":null,"evidence_url":"https://openlibrary.org/books/OL37806976M","evidence":[{"url":"https://openlibrary.org/books/OL37806976M","isbn":"9789029043151","checkedAt":"2026-10-31","facts":"OL currently attaches this exact fifth-volume edition to Children of Dune. Keep corrected internal Work311; verify scanned cover/title/author/ISBN independently. Do not weaken automatic parent validation. Add only an explicit reviewed edition-bound metadata row.","format":"paperback","language":"dut"},{"url":"https://www.bol.com/be/nl/p/ketters-van-duin/1001004005148617/","role":"Independent exact-edition identity/language corroboration","checkedAt":"2026-10-31"}],"review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"reviewed-cover:9789029043151"},{"relation":"catalog_work_descriptions","key":{"work_id":208,"language":"nl"},"before":null,"after":{"work_id":208,"language":"nl","bound_author_id":127,"text":"Lauren Olamina groeit op in een ommuurde gemeenschap in Californië, terwijl klimaatproblemen en economische ontwrichting het leven daarbuiten gevaarlijk maken. Door haar hyperempathie ervaart zij de pijn van anderen bijzonder sterk. Wanneer de veiligheid van haar woonplaats wegvalt, moet ze een bestaan buiten de muren zien op te bouwen. Haar zoektocht naar bescherming en medestanders gaat samen met het ontwikkelen van eigen ideeën over verandering en de toekomst.","source_type":"official_publisher","source_name":"A.W. Bruna","source_url":"https://www.awbruna.nl/boek/romans/octavia-butler/de-zaaier/","evidence":[{"url":"https://www.awbruna.nl/boek/romans/octavia-butler/de-zaaier/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:208:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2600,"language":"nl"},"before":null,"after":{"work_id":2600,"language":"nl","bound_author_id":8,"text":"Sneeuwman probeert te overleven nadat een ramp de menselijke samenleving heeft verwoest. Ooit heette hij Jimmy; nu leeft hij tussen genetisch veranderde wezens en herinneringen aan zijn vriend Crake en de raadselachtige Oryx. Zijn tocht door wat van de beschaving is overgebleven, brengt het verleden steeds dichterbij. Langzaam ontstaat een beeld van wetenschappelijke experimenten, commerciële macht en persoonlijke relaties die samen naar deze ontwrichte wereld hebben geleid.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/6113/oryx-and-crake-by-margaret-atwood/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/6113/oryx-and-crake-by-margaret-atwood/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2600:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2600,"language":"en"},"before":null,"after":{"work_id":2600,"language":"en","bound_author_id":8,"text":"Snowman survives among altered creatures in a landscape left behind by a devastating catastrophe. Remembering his earlier life as Jimmy, he returns in thought to his friend Crake and the elusive Oryx. His search for answers takes him through the remains of a society shaped by powerful companies and genetic experiments. The story moves between personal attachments and a civilisation whose attempts to redesign life have escaped their makers'' control.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/6113/oryx-and-crake-by-margaret-atwood/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/6113/oryx-and-crake-by-margaret-atwood/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2600:en"},{"relation":"catalog_work_descriptions","key":{"work_id":100,"language":"nl"},"before":null,"after":{"work_id":100,"language":"nl","bound_author_id":87,"text":"Jonas leeft in een gemeenschap waar duidelijke regels en toegewezen taken onzekerheid lijken uit te sluiten. Als hij twaalf wordt, krijgt hij een bijzondere opdracht: hij moet de herinneringen van de samenleving bewaren. Zijn leermeester laat hem ervaringen kennen die voor anderen verborgen blijven. Daardoor begint Jonas te begrijpen wat zijn veilige wereld heeft opgegeven en welke vragen haar bewoners niet meer stellen. Zijn nieuwe kennis maakt gehoorzamen steeds minder vanzelfsprekend.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/336799/the-giver.html","evidence":[{"url":"https://metadata.isbn.nl/336799/the-giver.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:100:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":100,"language":"en"},"before":null,"after":{"work_id":100,"language":"en","bound_author_id":87,"text":"Jonas grows up in a community organised around rules, assigned responsibilities and the promise of a predictable life. At twelve he receives an unusual role: preserving memories that other people no longer share. Training with the Giver introduces him to experiences excluded from everyday life. As he learns what his society has chosen to forget, the security he once accepted begins to look different, and following the rules becomes increasingly difficult.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/336799/the-giver.html","evidence":[{"url":"https://metadata.isbn.nl/336799/the-giver.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:100:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2717,"language":"nl"},"before":null,"after":{"work_id":2717,"language":"nl","bound_author_id":1307,"text":"Citra en Rowan leven in een wereld waar ziekte, honger en een natuurlijke dood zijn verdwenen. Om de bevolking te begrenzen, beëindigt een speciale orde toch mensenlevens. Tegen hun zin worden de twee jongeren voor die taak opgeleid. Tijdens hun leertijd moeten ze bepalen hoe zij omgaan met macht over anderen. Wat als een perfecte samenleving wordt voorgesteld, blijkt hen voor keuzes te plaatsen waarvoor geen eenvoudige of onschuldige oplossing bestaat.","source_type":"official_publisher","source_name":"Pelckmans","source_url":"https://www.pelckmansuitgevers.be/zeis.html","evidence":[{"url":"https://www.pelckmansuitgevers.be/zeis.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2717:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2717,"language":"en"},"before":null,"after":{"work_id":2717,"language":"en","bound_author_id":1307,"text":"Citra and Rowan live in a world that has overcome disease, hunger and natural death. Population control has become the responsibility of scythes, a special order authorised to end lives. Neither teenager wants to join, yet both are selected for training. Their apprenticeship forces them to confront the use of power over other people and the rules meant to restrain it. An apparently perfected society leaves them facing choices that are anything but simple.","source_type":"official_publisher","source_name":"Pelckmans","source_url":"https://www.pelckmansuitgevers.be/zeis.html","evidence":[{"url":"https://www.pelckmansuitgevers.be/zeis.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2717:en"},{"relation":"catalog_work_descriptions","key":{"work_id":179,"language":"nl"},"before":null,"after":{"work_id":179,"language":"nl","bound_author_id":135,"text":"In een toekomstig Chicago behoort iedereen tot een van vijf facties, elk gebouwd rond een bepaalde deugd. Op haar zestiende moet Beatrice Prior kiezen waar zij voortaan bij wil horen. Die beslissing kan haar van haar familie scheiden en bepaalt hoe zij zal moeten leven. Terwijl ze haar plaats probeert te vinden, botst haar eigen identiteit met een systeem dat mensen het liefst in vaste groepen onderbrengt.","source_type":"official_publisher","source_name":"Lannoo / Unieboek Spectrum","source_url":"https://www.lannoo.com/nl-nl/young-adult/inwijding-9789047516835","evidence":[{"url":"https://www.lannoo.com/nl-nl/young-adult/inwijding-9789047516835","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:179:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":179,"language":"en"},"before":null,"after":{"work_id":179,"language":"en","bound_author_id":135,"text":"In a future Chicago, society is divided into five factions, each organised around a different virtue. Sixteen-year-old Beatrice Prior must choose the group that will shape the rest of her life. The decision sets her loyalty to her family against her understanding of herself. As she tries to establish a place in this world, the demands of belonging reveal how difficult it is to fit a person into a single prescribed identity.","source_type":"official_publisher","source_name":"Lannoo / Unieboek Spectrum","source_url":"https://www.lannoo.com/nl-nl/young-adult/inwijding-9789047516835","evidence":[{"url":"https://www.lannoo.com/nl-nl/young-adult/inwijding-9789047516835","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:179:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2724,"language":"nl"},"before":null,"after":{"work_id":2724,"language":"nl","bound_author_id":1307,"text":"In een toekomstig Amerika mogen volwassenen bepaalde jongeren laten opsplitsen, waarna hun lichaamsdelen als donororganen worden gebruikt. Connor, Risa en Lev hebben ieder een andere achtergrond, maar dreigen hetzelfde lot te ondergaan. Wanneer hun wegen elkaar kruisen, proberen ze aan het systeem te ontsnappen. Hun vlucht dwingt hen samen te werken en te onderzoeken wie hen kan helpen in een samenleving die hun bestaan als vervangbare onderdelen beschouwt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1274116/gesplitst.html","evidence":[{"url":"https://metadata.isbn.nl/1274116/gesplitst.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2724:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2724,"language":"en"},"before":null,"after":{"work_id":2724,"language":"en","bound_author_id":1307,"text":"A future American society has found a disturbing compromise over the value of life: some teenagers can be dismantled and their organs used by others. Connor, Risa and Lev reach this threat from very different circumstances. When their paths cross, they seek a way out together. Escaping requires more than staying ahead of the authorities; they must decide whom to trust in a world that has made their bodies useful while denying their independence.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1274116/gesplitst.html","evidence":[{"url":"https://metadata.isbn.nl/1274116/gesplitst.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2724:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2846,"language":"nl"},"before":null,"after":{"work_id":2846,"language":"nl","bound_author_id":8,"text":"Een vernietigende epidemie heeft vrijwel alle mensen weggevaagd. Ren en Toby overleven op verschillende afgesloten plekken: de een in een exclusieve club, de ander in een luxe kuuroord. Buiten hun schuilplaatsen liggen de resten van een wereld vol machtsmisbruik en genetisch veranderde levensvormen. Terwijl afzondering niet langer houdbaar blijkt, moeten zij bepalen hoe ze verder kunnen. Hun ervaringen bieden een ander perspectief op de ontwrichte samenleving van Oryx en Crake.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/6130/the-year-of-the-flood-by-margaret-atwood/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/6130/the-year-of-the-flood-by-margaret-atwood/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2846:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2846,"language":"en"},"before":null,"after":{"work_id":2846,"language":"en","bound_author_id":8,"text":"A catastrophic epidemic has swept away most human life. Ren and Toby survive in separate refuges, one in an exclusive club and the other in a luxurious spa. Beyond those temporary shelters lies a world shaped by corrupt power and genetically altered organisms. Remaining hidden cannot last indefinitely, and both women must consider what comes next. Their experiences offer another view of the damaged society explored in Oryx and Crake.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/6130/the-year-of-the-flood-by-margaret-atwood/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/6130/the-year-of-the-flood-by-margaret-atwood/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2846:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2165,"language":"nl"},"before":null,"after":{"work_id":2165,"language":"nl","bound_author_id":7,"text":"Paul Atreides is keizer geworden, maar zijn overwinning heeft de onrust in het rijk niet beëindigd. Oorlog en de gevolgen van zijn groeiende macht tekenen het bestaan van miljarden mensen. Rond de heerser ontstaan plannen om zijn positie te ondermijnen, ook binnen kringen die hij vertrouwd acht. Het tweede Duin-boek volgt de spanning tussen het beeld van een machtige verlosser en de gevolgen van een heerschappij die steeds moeilijker te beheersen is.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783371/duin-messias.html","evidence":[{"url":"https://metadata.isbn.nl/1783371/duin-messias.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2165:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2165,"language":"en"},"before":null,"after":{"work_id":2165,"language":"en","bound_author_id":7,"text":"Paul Atreides rules an empire, but victory has not brought the peace he hoped for. The violence associated with his rise continues, while plots form around the throne. Open enemies are not the only threat: people close to him have interests of their own. The second Dune novel examines the distance between a ruler''s apparent power and his ability to control what others do in his name, as political and personal pressures converge.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783371/duin-messias.html","evidence":[{"url":"https://metadata.isbn.nl/1783371/duin-messias.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2165:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2169,"language":"nl"},"before":null,"after":{"work_id":2169,"language":"nl","bound_author_id":7,"text":"Arrakis verandert langzaam van een woestijnplaneet in een groenere wereld. Leto en Ghanima, de kinderen van Muad''Dib, groeien ondertussen op met verwachtingen over hun plaats op de keizerlijke troon en in de religie van de Vrijmans. Hun tante Alia wil hun bijzondere gaven inzetten tegen vijanden van de familie. De tweeling heeft echter eigen plannen. De strijd om hun toekomst raakt zo verbonden met de veranderende planeet en de machtsverhoudingen binnen het rijk.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783372/kinderen-van-duin.html","evidence":[{"url":"https://metadata.isbn.nl/1783372/kinderen-van-duin.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2169:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2169,"language":"en"},"before":null,"after":{"work_id":2169,"language":"en","bound_author_id":7,"text":"Arrakis is becoming greener, but the children of Muad''Dib still live amid struggles over the future of their family and world. The twins Leto and Ghanima are being prepared for important roles in imperial rule and Fremen religion. Their aunt Alia sees their unusual abilities as a way to defeat the family''s enemies. The children have purposes of their own, bringing their decisions into conflict with the ambitions surrounding them.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783372/kinderen-van-duin.html","evidence":[{"url":"https://metadata.isbn.nl/1783372/kinderen-van-duin.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2169:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2176,"language":"nl"},"before":null,"after":{"work_id":2176,"language":"nl","bound_author_id":7,"text":"Duizenden jaren na de gebeurtenissen rond Paul Atreides wordt het rijk beheerst door de vrijwel onsterfelijke Leto II. Zijn macht berust mede op een streng beheer van de steeds schaarser wordende specerij. Achter zijn tirannieke bestuur ligt een visie op de toekomst van de mensheid, maar uitvoering daarvan brengt grote risico''s met zich mee. Het vierde Duin-boek onderzoekt de spanning tussen een heerser die ver vooruit kijkt en degenen die onder zijn gezag moeten leven.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783344/god-keizer-op-duin.html","evidence":[{"url":"https://metadata.isbn.nl/1783344/god-keizer-op-duin.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2176:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2176,"language":"en"},"before":null,"after":{"work_id":2176,"language":"en","bound_author_id":7,"text":"Thousands of years after Paul Atreides, the nearly immortal Leto II holds power over the empire. By controlling the increasingly scarce spice, he maintains a rule that seems to have moved far beyond ordinary humanity. His understanding of the future gives his actions a purpose other people cannot easily share. The fourth Dune novel places that long view beside the cost of authoritarian power, asking what survival might demand from ruler and subjects alike.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783344/god-keizer-op-duin.html","evidence":[{"url":"https://metadata.isbn.nl/1783344/god-keizer-op-duin.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2176:en"},{"relation":"catalog_work_descriptions","key":{"work_id":311,"language":"nl"},"before":null,"after":{"work_id":311,"language":"nl","bound_author_id":7,"text":"Na de heerschappij van Leto II zijn grote groepen mensen het bekende rijk uitgetrokken. Hun terugkeer brengt nieuwe machtsstrijd naar een beschaving die inmiddels sterk is veranderd. Op Rakis, het vroegere Arrakis, krijgt een meisje met bijzondere vermogens steeds meer betekenis. Verschillende partijen proberen haar plaats in hun plannen te bepalen. De Bene Gesserit moeten daarbij afwegen of hun oude werkwijzen nog passen bij de gevaren en mogelijkheden van deze nieuwe tijd.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/303821/heretics-of-dune-by-frank-herbert/paperback/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/303821/heretics-of-dune-by-frank-herbert/paperback/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:311:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":311,"language":"en"},"before":null,"after":{"work_id":311,"language":"en","bound_author_id":7,"text":"Long after Leto II''s rule, people who left the old empire are returning with ambitions of their own. Rakis, once Arrakis, has become a desert world again, and its sandworms are dying. A girl called Sheeana attracts attention through an unusual connection with them. As rival factions compete for influence, the Bene Gesserit must weigh their traditions against changing circumstances. The fifth Dune novel follows power, belief and survival across the remnants of the empire.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/303821/heretics-of-dune-by-frank-herbert/paperback/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/303821/heretics-of-dune-by-frank-herbert/paperback/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:311:en"},{"relation":"catalog_work_descriptions","key":{"work_id":2182,"language":"nl"},"before":null,"after":{"work_id":2182,"language":"nl","bound_author_id":7,"text":"De strijd tussen de Bene Gesserit en de Achtenswaarde Matres bedreigt steeds meer werelden. Teruggekeerde groepen uit de Verstrooiing onderwerpen het oude rijk met geweld, terwijl de Zusters hun eigen voortbestaan proberen veilig te stellen. Eerdere ervaringen onder de heerschappij van Leto II werken door in hun keuzes. Het zesde Duin-boek volgt een conflict waarin politieke strategie, oude kennis en veranderende omstandigheden samen bepalen welke toekomst nog mogelijk is.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","evidence":[{"url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2182:nl"},{"relation":"catalog_work_descriptions","key":{"work_id":2182,"language":"en"},"before":null,"after":{"work_id":2182,"language":"en","bound_author_id":7,"text":"Conflict between the Bene Gesserit and the Honored Matres threatens the remaining worlds of the old empire. Groups returning from the Scattering bring overwhelming force, while the Sisterhood seeks a way to survive without surrendering its purpose. Lessons from the long reign of Leto II still shape its decisions. The sixth Dune novel follows a struggle in which inherited knowledge and political strategy must respond to enemies who have changed the balance of power.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","evidence":[{"url":"https://metadata.isbn.nl/1783348/duin-kapittel.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written summary. Description language is NOT edition-language evidence."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"dystopia-dune-editions-20261031"},"origin":"summary:2182:en"}],"bindings":[{"work":{"id":8,"title":"Dune","cover_id":null,"subjects":null,"subtitle":null,"author_id":7,"work_type":null,"created_at":"2026-09-01T06:02:03.100469+00:00","source_type":"open_library","open_library_id":"OL893414W","first_publish_year":1965,"native_identity_key":null},"author":{"id":7,"name":"Frank Herbert","created_at":"2026-09-01T06:02:02.944086+00:00","open_library_id":"OL79034A"}},{"work":{"id":100,"title":"The Giver","cover_id":null,"subjects":null,"subtitle":null,"author_id":87,"work_type":null,"created_at":"2026-09-01T15:21:20.76221+00:00","source_type":"open_library","open_library_id":"OL1846076W","first_publish_year":1993,"native_identity_key":null},"aut